/**
 * PlainAxis — A simple line-based axis mesh similar to Blender's "Empty - Plain Axes".
 * Draws full X, Y, Z axes crossing at the origin.
 *
 * @augments THREE.LineSegments
 *
 * @example
 * const axis = new PlainAxis(1);
 * scene.add(axis);
 */
export class PlainAxis {
    /**
   * Constructs a new PlainAxis.
   *
   * @param {number} [size=1] - Length from center to each end. Total per-axis length = 2×size.
   * @param {Object} [colors] - Optional axis colors.
   * @param {(number|string|THREE.Color)} [colors.x=0xff0000] - X axis color.
   * @param {(number|string|THREE.Color)} [colors.y=0x00ff00] - Y axis color.
   * @param {(number|string|THREE.Color)} [colors.z=0x0000ff] - Z axis color.
   */
    constructor(size?: number, colors?: {
        x?: (number | string | THREE.Color);
        y?: (number | string | THREE.Color);
        z?: (number | string | THREE.Color);
    });
    /**
 * Type marker.
 * @type {string}
 * @default 'PlainAxis'
 */
    type: string;
    /**
   * Update axis colors.
   * @param {(number|THREE.Color|string)} xAxisColor - New color for X axis.
   * @param {(number|THREE.Color|string)} yAxisColor - New color for Y axis.
   * @param {(number|THREE.Color|string)} zAxisColor - New color for Z axis.
   * @returns {PlainAxis}
   */
    setColors(xAxisColor: (number | THREE.Color | string), yAxisColor: (number | THREE.Color | string), zAxisColor: (number | THREE.Color | string)): PlainAxis;
    /**
   * Dispose GPU resources used by this helper.
   * @returns {void}
   */
    dispose(): void;
}
